<?php $e = fn ($v) => App\Core\View::e((string) $v); ?>
<section class="public-news"><header><p class="eyebrow"><?= $e($championship['name']) ?></p><h1>Vai e Vem</h1><p>Movimentacoes publicadas do campeonato.</p></header><form class="filter-bar" method="get" action="<?= $e(App\Core\Config::url('/campeonatos/' . $championship['slug'] . '/vai-e-vem')) ?>"><label>Buscar <input name="q" value="<?= $e($filters['q']) ?>"></label><label>Tipo <select name="type"><option value="">Todos</option><?php foreach ($types as $type): ?><option value="<?= $e($type) ?>" <?= $filters['type'] === $type ? 'selected' : '' ?>><?= $e($type) ?></option><?php endforeach; ?></select></label><button type="submit">Buscar</button></form><div class="news-grid"><?php foreach ($items as $item): ?><article class="news-card"><?php if ($item['photo_path']): ?><img src="<?= $e(App\Core\Config::url('/campeonatos/' . $championship['slug'] . '/vai-e-vem/' . $item['id'] . '/foto')) ?>" alt="Foto de <?= $e($item['athlete_name']) ?>"><?php endif; ?><p class="eyebrow"><?= $e($item['type']) ?> · <?= $e($item['movement_date']) ?></p><h2><?= $e($item['sporting_name'] ?: $item['athlete_name']) ?></h2><p><?= $e($item['previous_team_name'] ?: '-') ?> → <?= $e($item['new_team_name'] ?: '-') ?></p><?php if ($item['public_observation']): ?><p><?= nl2br($e($item['public_observation'])) ?></p><?php endif; ?></article><?php endforeach; ?></div><?php if (!$items): ?><p>Nenhuma movimentação publicada.</p><?php endif; ?><?php if ($pages > 1): ?><nav class="pagination" aria-label="Paginação"><?php for ($i = 1; $i <= $pages; $i++): ?><a class="<?= $i === $page ? 'active' : '' ?>" href="<?= $e(App\Core\Config::url('/campeonatos/' . $championship['slug'] . '/vai-e-vem?page=' . $i . '&q=' . urlencode($filters['q']) . '&type=' . urlencode($filters['type']))) ?>"><?= $i ?></a><?php endfor; ?></nav><?php endif; ?></section>
